SELECT 
FROM t_rob_order o
WHERE o.is_deleted = 0

    AND o.buyer_id = #{buyerId}


    AND o.session_id = #{sessionId}


    AND (
        o.buyer_name LIKE CONCAT('%', #{keyword}, '%')
        OR o.buyer_phone LIKE CONCAT('%', #{keyword}, '%')
        OR o.goods_name LIKE CONCAT('%', #{keyword}, '%')
        OR o.goods_sn LIKE CONCAT('%', #{keyword}, '%')
        OR CAST(o.buyer_id AS CHAR) LIKE CONCAT('%', #{keyword}, '%')
    )


    AND CAST(o.total_amount AS CHAR) LIKE CONCAT('%', #{amount}, '%')


    AND o.order_status = #{orderStatus}


    AND o.create_time >= #{startTime}


    AND o.create_time <= #{endTime}

ORDER BY o.create_time DESC, o.id DESC

SELECT COUNT(1)
FROM t_rob_order
WHERE is_deleted = 0
  AND order_status = 1
  AND buyer_id = #{buyerId}
  AND session_id = #{sessionId}

SELECT COUNT(1)
FROM t_rob_order
WHERE is_deleted = 0
  AND order_status = 1
  AND buyer_id = #{buyerId}
  AND create_time >= #{startTime}
  AND create_time <= #{endTime}
